// ---------- Nail color -> outfit matching ----------
const NAIL_SWATCHES = [
  { id: "nude", label: "Nude", hex: "#D8B49A", families: ["neutral", "dorado", "nude"] },
  { id: "rosa", label: "Rosa clásico", hex: "#F2A6C6", families: ["rosa", "neutral", "dorado"] },
  { id: "coral", label: "Coral/Durazno", hex: "#FF8C69", families: ["coral", "dorado", "nude"] },
  { id: "rojo", label: "Rojo", hex: "#B3121E", families: ["rojo", "dorado", "negro"] },
  { id: "negro", label: "Negro", hex: "#1A1A1A", families: ["negro", "plateado", "neutral"] },
  { id: "francesa", label: "Francesa", hex: "#FDF6EC", families: ["neutral", "dorado", "plateado"] },
  { id: "doradoazul", label: "Dorado + Azul", hex: "#8FBFD9", families: ["dorado", "azul", "plateado"] },
];

const HAIR_DAYS = [
  { day: 0, label: "Recién lavado" },
  { day: 1, label: "Día 1" },
  { day: 2, label: "Día 2" },
  { day: 3, label: "Día 3+" },
];

// Buckets an arbitrary hex color into a "family" so custom nail colors can
// also filter the dice pool, using the same family tags as NAIL_SWATCHES.
function hexToFamilies(hex) {
  try {
    const c = hex.replace("#", "");
    const r = parseInt(c.substring(0, 2), 16) / 255;
    const g = parseInt(c.substring(2, 4), 16) / 255;
    const b = parseInt(c.substring(4, 6), 16) / 255;
    const max = Math.max(r, g, b),
      min = Math.min(r, g, b);
    const l = (max + min) / 2;
    let h = 0,
      s = 0;
    if (max !== min) {
      const d = max - min;
      s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
      switch (max) {
        case r:
          h = (g - b) / d + (g < b ? 6 : 0);
          break;
        case g:
          h = (b - r) / d + 2;
          break;
        case b:
          h = (r - g) / d + 4;
          break;
      }
      h *= 60;
    }
    if (l < 0.18) return ["negro"];
    if (l > 0.88 && s < 0.25) return ["neutral", "nude"];
    if (s < 0.18) return ["neutral", "plateado"];
    if (h < 20 || h >= 345) return ["rojo"];
    if (h < 45) return ["coral", "dorado"];
    if (h < 65) return ["dorado"];
    if (h < 170) return ["verde"];
    if (h < 250) return ["azul"];
    return ["rosa"];
  } catch {
    return [];
  }
}

// A face with no colorFamilies is "universal" and always passes the filter.
// A face WITH colorFamilies only passes if it overlaps the active nail families.
function facePassesNail(face, activeFamilies) {
  if (!activeFamilies || activeFamilies.length === 0) return true;
  if (!face.colorFamilies || face.colorFamilies.length === 0) return true;
  return face.colorFamilies.some((f) => activeFamilies.includes(f));
}

// A face with no hairDayMin works on freshly washed hair too.
// A face WITH hairDayMin only passes if the hair has had at least that many days of texture/grip.
function facePassesHairDay(face, activeHairDay) {
  if (activeHairDay === null || activeHairDay === undefined) return true;
  if (face.hairDayMin === undefined) return true;
  return activeHairDay >= face.hairDayMin;
}

function weightedPick(pool, prefMap) {
  // Weight is capped so a piece rated 4-5⭐ many times over doesn't end up
  // as the only realistic outcome — it gets favored, not forced.
  const weights = pool.map((f) => 1 + 2 * Math.min(prefMap?.[f.n] || 0, 3));
  const total = weights.reduce((a, b) => a + b, 0);
  let r = Math.random() * total;
  for (let i = 0; i < pool.length; i++) {
    r -= weights[i];
    if (r <= 0) return pool[i];
  }
  return pool[pool.length - 1];
}

function rollFace(faces, vibeId, prefMap, activeNailFamilies, activeHairDay) {
  let pool =
    vibeId === "wildcard"
      ? faces
      : faces.filter((f) => f.v.includes(vibeId)).length
      ? faces.filter((f) => f.v.includes(vibeId))
      : faces;
  // Filter by nail color compatibility, but never leave an empty pool.
  const colorFiltered = pool.filter((f) => facePassesNail(f, activeNailFamilies));
  if (colorFiltered.length) pool = colorFiltered;
  // Filter by hair-day compatibility (only meaningful for the hair dice), same fallback rule.
  const hairDayFiltered = pool.filter((f) => facePassesHairDay(f, activeHairDay));
  if (hairDayFiltered.length) pool = hairDayFiltered;
  return weightedPick(pool, prefMap);
}

